import React from 'react';
import ReactDOM from 'react-dom/client';

function App() {
  return (
    <div style={{ 
      textAlign: 'center', 
      padding: '50px',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h1 style={{ color: '#2563eb' }}>🚗 Auto Service Platform</h1>
      <p>Welcome to your Auto Service Platform!</p>
      <p>Backend Status: 
        <button 
          onClick={async () => {
            const res = await fetch('http://localhost:5000/api/health');
            const data = await res.json();
            alert('Backend is ' + data.status);
          }}
          style={{ marginLeft: '10px', padding: '5px 10px', cursor: 'pointer' }}
        >
          Test Backend
        </button>
      </p>
      <hr />
      <h3>Features Coming Soon:</h3>
      <ul style={{ textAlign: 'left', display: 'inline-block' }}>
        <li>✅ Multi-role Login (Customer/Provider/Driver/Admin)</li>
        <li>✅ Book Auto Services</li>
        <li>✅ Concierge Driver Service</li>
        <li>✅ Online Payments</li>
        <li>✅ Reviews & Ratings</li>
      </ul>
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
